const listConversationsForUser = `-- name: ListConversationsForUser :many
SELECT
    c.id,
    c.type,
    c.status,
    c.initiated_by,
    c.last_message_sequence,
    c.created_at,
    c.updated_at,
    cm.last_read_sequence,
    cm.receipt_sequence,
    (CASE WHEN c.user_a_id = $1::uuid THEN c.user_b_id ELSE c.user_a_id END)::uuid AS peer_id,
    u.username AS peer_username,
    u.display_name AS peer_display_name,
    u.bio AS peer_bio,
    u.avatar_url AS peer_avatar_url,
    (
        SELECT count(*)
        FROM messages m
        WHERE m.conversation_id = c.id
          AND m.sequence_num > cm.last_read_sequence
          AND m.sender_id != $1::uuid
          AND m.deleted_at IS NULL
    ) AS unread_count,
    COALESCE(lm.id::text, '')::text AS last_message_id,
    COALESCE(lm.sender_id::text, '')::text AS last_message_sender_id,
    COALESCE(lm.content, '')::text AS last_message_content,
    lm.created_at AS last_message_created_at
FROM conversations c
JOIN conversation_members cm ON cm.conversation_id = c.id AND cm.user_id = $1::uuid
JOIN users u ON u.id = CASE WHEN c.user_a_id = $1::uuid THEN c.user_b_id ELSE c.user_a_id END
LEFT JOIN LATERAL (
    SELECT id, sender_id, content, created_at
    FROM messages
    WHERE conversation_id = c.id AND deleted_at IS NULL
    ORDER BY sequence_num DESC
    LIMIT 1
) lm ON true
ORDER BY c.updated_at DESC
`

type ListConversationsForUserRow struct {
	ID                   string             `json:"id"`
	Type                 string             `json:"type"`
	Status               string             `json:"status"`
	InitiatedBy          string             `json:"initiated_by"`
	LastMessageSequence  int64              `json:"last_message_sequence"`
	CreatedAt            pgtype.Timestamptz `json:"created_at"`
	UpdatedAt            pgtype.Timestamptz `json:"updated_at"`
	LastReadSequence     int64              `json:"last_read_sequence"`
	ReceiptSequence      int64              `json:"receipt_sequence"`
	PeerID               string             `json:"peer_id"`
	PeerUsername         *string            `json:"peer_username"`
	PeerDisplayName      *string            `json:"peer_display_name"`
	PeerBio              *string            `json:"peer_bio"`
	PeerAvatarUrl        *string            `json:"peer_avatar_url"`
	UnreadCount          int64              `json:"unread_count"`
	LastMessageID        string             `json:"last_message_id"`
	LastMessageSenderID  string             `json:"last_message_sender_id"`
	LastMessageContent   string             `json:"last_message_content"`
	LastMessageCreatedAt pgtype.Timestamptz `json:"last_message_created_at"`
}

func (q *Queries) ListConversationsForUser(ctx context.Context, userID string) ([]ListConversationsForUserRow, error) {
	rows, err := q.db.Query(ctx, listConversationsForUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListConversationsForUserRow{}
	for rows.Next() {
		var i ListConversationsForUserRow
		if err := rows.Scan(
			&i.ID,
			&i.Type,
			&i.Status,
			&i.InitiatedBy,
			&i.LastMessageSequence,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.LastReadSequence,
			&i.ReceiptSequence,
			&i.PeerID,
			&i.PeerUsername,
			&i.PeerDisplayName,
			&i.PeerBio,
			&i.PeerAvatarUrl,
			&i.UnreadCount,
			&i.LastMessageID,
			&i.LastMessageSenderID,
			&i.LastMessageContent,
			&i.LastMessageCreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

